on conflict(slug) do update set name=excluded.name,canonical_name=excluded.canonical_name,aliases=excluded.aliases,primary_muscle=excluded.primary_muscle,secondary_muscles=excluded.secondary_muscles,body_region=excluded.body_region,movement_type=excluded.movement_type,movement_pattern=excluded.movement_pattern,equipment=excluded.equipment,laterality=excluded.laterality,exercise_type=excluded.exercise_type,difficulty=excluded.difficulty,setup_instructions=excluded.setup_instructions,movement_instructions=excluded.movement_instructions,cue=excluded.cue,common_mistakes=excluded.common_mistakes,rest_min_seconds=excluded.rest_min_seconds,rest_max_seconds=excluded.rest_max_seconds,substitution_group=excluded.substitution_group,thumbnail_url=excluded.thumbnail_url,image_url=excluded.image_url,motion_url=excluded.motion_url,motion_kind=excluded.motion_kind,load_basis=excluded.load_basis,is_legacy=excluded.is_legacy,default_rest_seconds=excluded.default_rest_seconds,animation_url=excluded.animation_url where exercises.owner_id is null;
-- Only non-Michael shared templates get more precise exercise choices. User plans are untouched.
update public.plan_day_exercises pe set exercise_id=e.id
from public.plan_days d, public.workout_plans p, public.exercises old, public.exercises e
where pe.day_id=d.id and d.plan_id=p.id and p.is_template=true and p.name<>'Michael Muscle Builder'
and pe.exercise_id=old.id and old.slug='leg-press-or-squat' and e.slug='leg-press' and e.owner_id is null;
update public.plan_day_exercises pe set exercise_id=e.id
from public.plan_days d, public.workout_plans p, public.exercises old, public.exercises e
where pe.day_id=d.id and d.plan_id=p.id and p.is_template=true and p.name<>'Michael Muscle Builder'
and pe.exercise_id=old.id and old.slug='walking-lunge-or-split-squat' and e.slug='reverse-lunge' and e.owner_id is null;
-- A named barbell press makes Strength Foundation's upper-body strength day clearer.
update public.plan_day_exercises pe set exercise_id=e.id
from public.plan_days d, public.workout_plans p, public.exercises old, public.exercises e
where pe.day_id=d.id and d.plan_id=p.id and p.is_template=true and p.name='Strength Foundation — 3 days'
and pe.exercise_id=old.id and old.slug='dumbbell-bench-press' and e.slug='barbell-bench-press' and e.owner_id is null;
